import{_ as t,o,c as i,a0 as a}from"./chunks/framework.OED5XGjC.js";const k=JSON.parse('{"title":"Set up myco on a repository","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/init-repo.md","filePath":"how-to/init-repo.md"}'),r={name:"how-to/init-repo.md"};function d(s,e,c,n,p,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="set-up-myco-on-a-repository" tabindex="-1">Set up myco on a repository <a class="header-anchor" href="#set-up-myco-on-a-repository" aria-label="Permalink to &quot;Set up myco on a repository&quot;">​</a></h1><p><code>myco init</code> turns any git repo into a myco project: an orphan <code>project</code> branch checked out as a <code>project/</code> worktree.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><h2 id="what-it-creates" tabindex="-1">What it creates <a class="header-anchor" href="#what-it-creates" aria-label="Permalink to &quot;What it creates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>path</th><th>what</th></tr></thead><tbody><tr><td><code>project/</code></td><td>git worktree on the orphan <code>project</code> branch</td></tr><tr><td><code>project/meta.toml</code></td><td>repo name + per-kind id counters (<code>[next]</code>)</td></tr><tr><td><code>project/TODO.md</code></td><td>active tasks</td></tr><tr><td><code>project/BACKLOG.md</code></td><td>deferred items</td></tr><tr><td><code>project/index.md</code></td><td>human-readable ledger index</td></tr><tr><td><code>project/issues/</code>, <code>proposals/</code>, <code>plans/</code>, <code>adrs/</code>, <code>handoffs/</code></td><td>file-backed item dirs</td></tr><tr><td><code>.gitignore</code> += <code>project/</code></td><td>keeps the worktree out of code commits</td></tr></tbody></table><p><code>init</code> commits the scaffold on the <code>project</code> branch — your code branch only gains the <code>.gitignore</code> line.</p><h2 id="re-running-init" tabindex="-1">Re-running init <a class="header-anchor" href="#re-running-init" aria-label="Permalink to &quot;Re-running init&quot;">​</a></h2><p><code>init</code> is idempotent: a valid existing worktree gets its scaffold verified/repaired instead of re-created. It is the safe &quot;is this repo set up?&quot; probe.</p><h2 id="overrides-and-discovery" tabindex="-1">Overrides and discovery <a class="header-anchor" href="#overrides-and-discovery" aria-label="Permalink to &quot;Overrides and discovery&quot;">​</a></h2><p><code>--root</code> picks the repo, <code>--dir</code> picks a non-default worktree path (init uses it instead of <code>&lt;root&gt;/project</code>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/GitHub/9aia/sepia</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/work/ledger</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # worktree somewhere else</span></span></code></pre></div><p>Every other verb discovers the project the same way, in order:</p><ol><li><code>--dir</code> — explicit worktree path</li><li><code>--root</code> — repo root (worktree is <code>&lt;root&gt;/project</code>)</li><li><code>project_dir</code> in <code>myco.toml</code> (see <a href="./../reference/config.html">config</a>)</li><li>walk up from cwd for a <code>project/</code> worktree on branch <code>project</code></li><li>cwd inside the worktree itself</li></ol><p>A non-standard worktree location stays discoverable if you set <code>project_dir</code> (relative to the repo root) in a <code>myco.toml</code> — the search order is <code>$MYCO_CONFIG</code> → <code>./myco.toml</code> (where you run <code>myco</code>) → <code>~/.config/myco/myco.toml</code>.</p><h2 id="if-the-repo-has-a-pm-dir" tabindex="-1">If the repo has a <code>pm/</code> dir <a class="header-anchor" href="#if-the-repo-has-a-pm-dir" aria-label="Permalink to &quot;If the repo has a `pm/` dir&quot;">​</a></h2><p>Don&#39;t <code>init</code> — run <a href="./migrate.html"><code>myco migrate</code></a> instead. It converts the legacy <code>pm/</code> layout into a fresh <code>project/</code> worktree in one pass.</p>',16)])])}const m=t(r,[["render",d]]);export{k as __pageData,m as default};
